export default function BlogPostPage() {
  const router = useRouter();
  const { slug } = useParams();
  const post = posts.find(p => p.slug === slug);

  if (!post) return (
    <div style={{ background: "#0A0A0A", minHeight: "100vh", display: "flex", alignItems: "center", justifyContent: "center", color: "#F0EDE8", fontFamily: "sans-serif" }}>
      <div style={{ textAlign: "center" }}>
        <div style={{ fontSize: 48, marginBottom: 16 }}>📝</div>
        <div style={{ fontSize: 18, fontWeight: 700, marginBottom: 16 }}>Post not found</div>
        <button onClick={() => router.push("/blog")} style={{ background: "#E8533A", border: "none", color: "#fff", padding: "10px 24px", borderRadius: 10, cursor: "pointer" }}>Back to Blog</button>
      </div>
    </div>
  );

  return (
    <div style={{ background: "#0A0A0A", minHeight: "100vh", color: "#F0EDE8", fontFamily: "sans-serif" }}>
      <div style={{ background: "rgba(255,255,255,0.03)", borderBottom: "1px solid rgba(255,255,255,0.07)", padding: "14px 24px", display: "flex", alignItems: "center", gap: 12 }}>
        <button onClick={() => router.push("/blog")} style={{ background: "none", border: "none", color: "#E8533A", cursor: "pointer", fontSize: 20 }}>←</button>
        <div style={{ fontWeight: 900, fontSize: 16 }}>🌍 Makola Digital Blog</div>
      </div>
      <div style={{ maxWidth: 720, margin: "0 auto", padding: "40px 24px" }}>
        <div style={{ display: "flex", gap: 8, marginBottom: 20, flexWrap: "wrap" }}>
          <span style={{ background: "rgba(232,83,58,0.12)", border: "1px solid rgba(232,83,58,0.2)", borderRadius: 20, padding: "2px 10px", fontSize: 11, color: "#E8533A", fontWeight: 700 }}>{post.category}</span>
          <span style={{ fontSize: 11, color: "rgba(240,237,232,0.4)" }}>{post.date} · {post.readTime}</span>
        </div>
        <h1 style={{ fontSize: 28, fontWeight: 900, marginBottom: 16, lineHeight: 1.3 }}>{post.title}</h1>
        <p style={{ fontSize: 16, color: "rgba(240,237,232,0.6)", marginBottom: 32, lineHeight: 1.7, borderBottom: "1px solid rgba(255,255,255,0.08)", paddingBottom: 24 }}>{post.excerpt}</p>
        <div style={{ fontSize: 15, lineHeight: 1.8, color: "rgba(240,237,232,0.85)" }} dangerouslySetInnerHTML={{ __html: post.content.replace(/<h2>/g, '<h2 style="font-size:20px;font-weight:800;margin:28px 0 12px;color:#F0EDE8">').replace(/<p>/g, '<p style="margin:0 0 16px">').replace(/<ul>/g, '<ul style="margin:0 0 16px;padding-left:20px">').replace(/<li>/g, '<li style="margin-bottom:8px">').replace(/<strong>/g, '<strong style="color:#F0EDE8">') }} />
        <div style={{ borderTop: "1px solid rgba(255,255,255,0.08)", paddingTop: 32, marginTop: 32 }}>
          <div style={{ fontWeight: 700, marginBottom: 16 }}>Ready to get started?</div>
          <div style={{ display: "flex", gap: 12, flexWrap: "wrap" }}>
            <button onClick={() => router.push("/auth/register")} style={{ background: "#E8533A", border: "none", color: "#fff", padding: "12px 24px", borderRadius: 10, fontSize: 14, fontWeight: 700, cursor: "pointer" }}>Start selling free →</button>
            <button onClick={() => router.push("/search")} style={{ background: "rgba(255,255,255,0.06)", border: "1px solid rgba(255,255,255,0.1)", color: "#F0EDE8", padding: "12px 24px", borderRadius: 10, fontSize: 14, cursor: "pointer" }}>Browse listings</button>
          </div>
        </div>
      </div>
    </div>
  );
}
